"""Custom scraper for The Sinclair events"""
import logging
import re
from datetime import datetime
from typing import List
from dateutil import parser as date_parser

from src.scrapers.base_scraper import BaseScraper
from src.models.event import EventCreate, EventCategory

logger = logging.getLogger(__name__)


class SinclairScraper(BaseScraper):
    """Custom scraper for The Sinclair events"""

    def __init__(self):
        super().__init__(
            source_name="The Sinclair",
            source_url="https://www.sinclaircambridge.com/events/",
            use_selenium=False
        )

    def scrape_events(self) -> List[EventCreate]:
        """Scrape events from The Sinclair"""
        events = []
        page = 1
        max_pages = 10

        while page <= max_pages:
            try:
                if page == 1:
                    url = self.source_url
                else:
                    url = f"https://www.sinclaircambridge.com/events/page/{page}/"

                html = self.fetch_html(url)
                soup = self.parse_html(html)

                event_items = soup.find_all('article', class_='event_item')

                if not event_items:
                    break

                for item in event_items:
                    try:
                        title_elem = item.find('h3', class_='event_title')
                        if not title_elem:
                            continue

                        title_link = title_elem.find('a')
                        if not title_link:
                            continue

                        title = self.clean_text(title_link.get_text())
                        event_url = title_link.get('href', '')

                        if not title or not event_url:
                            continue

                        date_elem = item.find('span', class_='event_date')
                        if not date_elem:
                            continue

                        date_text = self.clean_text(date_elem.get_text())

                        time_elem = item.find('span', class_='event_time')
                        time_text = ''
                        if time_elem:
                            time_text = self.clean_text(time_elem.get_text())

                        try:
                            if time_text:
                                datetime_str = f"{date_text} {time_text}"
                                start_datetime = date_parser.parse(datetime_str, fuzzy=True)
                            else:
                                start_datetime = date_parser.parse(date_text, fuzzy=True)
                        except Exception as e:
                            logger.warning(f"Failed to parse date '{date_text} {time_text}': {str(e)}")
                            continue

                        desc_elem = item.find('div', class_='event_description')
                        description = ''
                        if desc_elem:
                            description = self.clean_text(desc_elem.get_text())

                        if not description:
                            description = f"{title} at The Sinclair in Cambridge, MA"

                        image_url = None
                        img_elem = item.find('img')
                        if img_elem:
                            image_url = img_elem.get('src') or img_elem.get('data-src')
                            if image_url and not image_url.startswith('http'):
                                if image_url.startswith('//'):
                                    image_url = f"https:{image_url}"
                                else:
                                    image_url = f"https://www.sinclaircambridge.com{image_url}"

                        if not image_url and event_url:
                            try:
                                detail_html = self.fetch_html(event_url)
                                detail_soup = self.parse_html(detail_html)
                                image_url = self.extract_image_url(detail_soup, event_url)
                            except Exception as e:
                                logger.warning(f"Failed to fetch image from detail page: {str(e)}")

                        cost_elem = item.find('span', class_='event_price')
                        cost = None
                        if cost_elem:
                            cost = self.clean_text(cost_elem.get_text())

                        age_elem = item.find('span', class_='event_age')
                        age_restrictions = None
                        if age_elem:
                            age_restrictions = self.clean_text(age_elem.get_text())

                        category = self.categorize_event(title, description)

                        event = EventCreate(
                            title=title[:200],
                            description=description[:2000],
                            start_datetime=start_datetime,
                            source_url=event_url,
                            source_name=self.source_name,
                            venue_name="The Sinclair",
                            street_address="52 Church Street",
                            city="Cambridge",
                            state="MA",
                            zip_code="02138",
                            category=category,
                            cost=cost,
                            age_restrictions=age_restrictions,
                            image_url=image_url
                        )
                        events.append(event)

                    except Exception as e:
                        logger.warning(f"Failed to parse event item: {str(e)}")
                        continue

                page += 1

            except Exception as e:
                logger.error(f"Failed to fetch page {page}: {str(e)}")
                break

        return events

    def categorize_event(self, title: str, description: str) -> EventCategory:
        """Categorize event based on keywords"""
        text = f"{title} {description}".lower()

        if any(word in text for word in ['concert', 'music', 'band', 'dj', 'live music', 'show', 'tour', 'performance']):
            return EventCategory.MUSIC
        elif any(word in text for word in ['comedy', 'stand-up', 'comedian']):
            return EventCategory.THEATER
        elif any(word in text for word in ['trivia', 'quiz']):
            return EventCategory.ARTS_CULTURE
        elif any(word in text for word in ['dance', 'dancing']):
            return EventCategory.ARTS_CULTURE
        else:
            return EventCategory.MUSIC

"""Custom scraper for Regent Theatre events"""
import logging
import re
from datetime import datetime
from typing import List
from dateutil import parser as date_parser
import xml.etree.ElementTree as ET

from src.scrapers.base_scraper import BaseScraper
from src.models.event import EventCreate, EventCategory

logger = logging.getLogger(__name__)


class RegentTheatreScraper(BaseScraper):
    """Custom scraper for Regent Theatre events using RSS feed"""

    def __init__(self):
        super().__init__(
            source_name="Regent Theatre",
            source_url="https://regenttheatre.com/feed/",
            use_selenium=False
        )

    def scrape_events(self) -> List[EventCreate]:
        """Scrape events from Regent Theatre RSS feed"""
        try:
            import requests
            response = requests.get(self.source_url, timeout=30, headers=self.get_browser_headers())
            response.raise_for_status()

            root = ET.fromstring(response.content)

            events = []

            for item in root.findall('.//item'):
                try:
                    title_elem = item.find('title')
                    if title_elem is None or not title_elem.text:
                        continue

                    title = self.clean_text(title_elem.text)

                    if len(title) < 3:
                        continue

                    link_elem = item.find('link')
                    event_url = link_elem.text if link_elem is not None and link_elem.text else self.source_url

                    description_elem = item.find('description')
                    description_html = description_elem.text if description_elem is not None else ""

                    if description_html:
                        soup = self.parse_html(description_html)
                        description = self.clean_text(soup.get_text())
                    else:
                        description = title

                    if len(description) > 2000:
                        description = description[:1997] + "..."

                    pub_date_elem = item.find('pubDate')
                    if pub_date_elem is not None and pub_date_elem.text:
                        try:
                            start_datetime = date_parser.parse(pub_date_elem.text)
                        except:
                            start_datetime = datetime.now()
                    else:
                        start_datetime = datetime.now()

                    content_encoded = item.find('.//{http://purl.org/rss/1.0/modules/content/}encoded')
                    if content_encoded is not None and content_encoded.text:
                        content_soup = self.parse_html(content_encoded.text)
                        content_text = content_soup.get_text()

                        if len(content_text) > len(description):
                            description = self.clean_text(content_text)
                            if len(description) > 2000:
                                description = description[:1997] + "..."

                    image_url = None

                    enclosure = item.find('enclosure')
                    if enclosure is not None:
                        enclosure_url = enclosure.get('url')
                        if enclosure_url and any(ext in enclosure_url.lower() for ext in ['.jpg', '.jpeg', '.png', '.webp']):
                            image_url = enclosure_url

                    if not image_url:
                        media_content = item.find('.//{http://search.yahoo.com/mrss/}content')
                        if media_content is not None:
                            image_url = media_content.get('url')

                    if not image_url and content_encoded is not None and content_encoded.text:
                        content_soup = self.parse_html(content_encoded.text)
                        img = content_soup.find('img')
                        if img:
                            image_url = img.get('src') or img.get('data-src')

                    if image_url and not image_url.startswith('http'):
                        if image_url.startswith('//'):
                            image_url = f'https:{image_url}'
                        else:
                            image_url = f'https://regenttheatre.com{image_url}'

                    cost = None
                    if description:
                        cost_match = re.search(r'\$\d+(?:\.\d{2})?', description)
                        if cost_match:
                            cost = cost_match.group()

                    category = self.categorize_event(title, description)

                    venue_name = "Regent Theatre"
                    street_address = "7 Medford St"
                    city = "Arlington"
                    state = "MA"
                    zip_code = "02474"

                    event = EventCreate(
                        title=title[:200],
                        description=description[:2000],
                        start_datetime=start_datetime,
                        source_url=event_url,
                        source_name=self.source_name,
                        venue_name=venue_name,
                        street_address=street_address,
                        city=city,
                        state=state,
                        zip_code=zip_code,
                        category=category,
                        cost=cost,
                        image_url=image_url
                    )
                    events.append(event)

                except Exception as e:
                    logger.warning(f"Failed to parse event from RSS item: {str(e)}")
                    continue

            return events

        except Exception as e:
            logger.error(f"Failed to scrape Regent Theatre RSS feed: {str(e)}")
            return []

    def categorize_event(self, title: str, description: str) -> EventCategory:
        """Categorize event based on keywords"""
        text = f"{title} {description}".lower()

        if any(word in text for word in ['concert', 'music', 'band', 'singer', 'orchestra', 'symphony', 'jazz', 'rock', 'pop', 'folk', 'acoustic']):
            return EventCategory.MUSIC
        elif any(word in text for word in ['comedy', 'stand-up', 'comedian', 'improv']):
            return EventCategory.THEATER
        elif any(word in text for word in ['play', 'theater', 'theatre', 'drama', 'musical', 'show', 'performance']):
            return EventCategory.THEATER
        elif any(word in text for word in ['film', 'movie', 'cinema', 'screening']):
            return EventCategory.ARTS_CULTURE
        elif any(word in text for word in ['lecture', 'talk', 'discussion', 'presentation', 'speaker']):
            return EventCategory.LECTURES
        elif any(word in text for word in ['art', 'exhibition', 'gallery', 'museum']):
            return EventCategory.ARTS_CULTURE
        elif any(word in text for word in ['dance', 'ballet', 'contemporary']):
            return EventCategory.ARTS_CULTURE
        else:
            return EventCategory.ARTS_CULTURE
